const lenses={people:{label:'THE HUMAN SIDE',title:'Start with the person.',description:'Testing user flows at PathSpark and leading activities at the YMCA taught me to look at the experience behind the process.',link:'#experience',cta:'Explore my experience ↗'},systems:{label:'THE CONNECTIONS',title:'Make the pieces work together.',description:'Relational databases and robot builds share a challenge: individual parts only become useful when their relationships make sense.',link:'#work',cta:'Explore the systems I’ve worked on ↗'},business:{label:'THE PRACTICAL QUESTION',title:'Understand what changes the outcome.',description:'Restaurant dashboards and profitability models let me explore how demand, ingredient costs, and waste relate to the business.',link:'#playground',cta:'Try a small experiment ↗'}};
document.querySelectorAll('[data-lens]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.lens,p=lenses[key];document.querySelectorAll('[data-lens]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lens===key)));document.querySelector('.orbit-map').dataset.active=key;document.querySelector('#lens-label').textContent=p.label;document.querySelector('#lens-title').textContent=p.title;document.querySelector('#lens-description').textContent=p.description;const link=document.querySelector('#lens-link');link.href=p.link;link.textContent=p.cta;}));
const tabs=[...document.querySelectorAll('.lab-tabs [role=tab]')];function selectTab(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;});}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{let target;if(e.key==='ArrowRight')target=tabs[(i+1)%tabs.length];if(e.key==='ArrowLeft')target=tabs[(i-1+tabs.length)%tabs.length];if(e.key==='Home')target=tabs[0];if(e.key==='End')target=tabs[tabs.length-1];if(target){e.preventDefault();selectTab(target);target.focus();}});});
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function calculate(){const orders=Number(document.querySelector('#orders').value),cost=Number(document.querySelector('#cost').value),waste=Number(document.querySelector('#waste').value);const revenue=orders*15,ingredients=orders*cost*(1+waste/100),profit=revenue-ingredients-5000,delta=profit-3400;document.querySelector('#orders-value').textContent=orders.toLocaleString();document.querySelector('#cost-value').textContent=money(cost).replace(/\.00$/,'')+(cost%1===0?'.00':'');document.querySelector('#cost-value').textContent='$'+cost.toFixed(2);document.querySelector('#waste-value').textContent=waste+'%';document.querySelector('#profit-value').textContent=money(profit);document.querySelector('#profit-comparison').textContent=Math.abs(delta)<.01?'Starting scenario':`${delta>=0?'↑':'↓'} ${money(Math.abs(delta))} ${delta>=0?'above':'below'} the starting scenario`;document.querySelector('#revenue-label').textContent=money(revenue);document.querySelector('#ingredients-label').textContent=money(ingredients);const max=Math.max(revenue,ingredients,5000);document.querySelector('#revenue-bar').style.width=revenue/max*100+'%';document.querySelector('#ingredients-bar').style.width=ingredients/max*100+'%';document.querySelector('#fixed-bar').style.width=5000/max*100+'%';document.querySelector('#model-insight').textContent=`Each percentage point of waste costs ${money(orders*cost/100)} per month in this scenario.`;}
['orders','cost','waste'].forEach(id=>document.getElementById(id).addEventListener('input',calculate));document.querySelector('#reset-model').addEventListener('click',()=>{document.querySelector('#orders').value=1000;document.querySelector('#cost').value=6;document.querySelector('#waste').value=10;calculate();});calculate();
const steps=[['TRANSACTION','It starts with a customer.','Order #1042 records one margherita pizza. An order-item record connects this transaction to a specific menu item.','order_id: 1042\nmenu_item_id: P01\nquantity: 1'],['CATALOG','Give every item an identity.','The menu item has a name and price. Its identifier links an order to the recipe used to make that item.','menu_item_id: P01\nname: Margherita pizza\nprice: $15.00\nrecipe_id: R01'],['RECIPE','Translate the sale into ingredients.','A recipe connects a menu item to the quantities of ingredients it needs. One pizza becomes a set of ingredient requirements.','recipe_id: R01\nflour: 250 g\ntomato: 80 g\nmozzarella: 100 g'],['INVENTORY','Compare expected use with stock.','Those recipe quantities imply ingredient usage. Comparing expected use with recorded inventory changes can help frame questions about waste or portioning.','ingredient: mozzarella\nstarting_stock: 5,000 g\nexpected_usage: 100 g\nexpected_remaining: 4,900 g']];document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const p=steps[Number(b.dataset.step)];['flow-kicker','flow-title','flow-description','flow-record'].forEach((id,i)=>document.getElementById(id).textContent=p[i]);}));
